#[test]
fn coarse_timestamps_skip_rounding_but_transfer_changed_bucket_or_size() {
    let mut source = entry("data", 5, 100, None);
    let mut destination = source.clone();
    source.mtime_nsec = 760;
    destination.mtime_nsec = 700;
    let source_manifest = manifest(vec![source]);
    let strict = Planner::default().plan(&source_manifest, &manifest(vec![destination.clone()]));
    assert_eq!(strict.updates.len(), 1);
    let coarse = Planner::new(PlannerConfig {
        timestamp_resolution_ns: 100,
        ..PlannerConfig::default()
    });
    assert_eq!(coarse.plan(&source_manifest, &manifest(vec![destination.clone()])).skips.len(), 1);
    destination.mtime_nsec = 800;
    assert_eq!(coarse.plan(&source_manifest, &manifest(vec![destination.clone()])).updates.len(), 1);
    destination.mtime_nsec = 700;
    destination.size += 1;
    assert_eq!(coarse.plan(&source_manifest, &manifest(vec![destination])).updates.len(), 1);
}

